import {Button, FormControl, TextInput} from '@primer/react'
import {Box, IconButton} from '@primer/styled-react'
import {PackageIcon, TrashIcon} from '@primer/octicons-react'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemLeadingVisual} from '@github-ui/list-view/ListItemLeadingVisual'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItem} from '@github-ui/list-view/ListItem'
import type {PrivateNetwork} from '../classes/private-network'
import {Dialog} from '@primer/styled-react/experimental'
import {useCallback, useState} from 'react'
import {PrivateNetworkConsts} from '../constants/private-network-consts'
import {PrivateNetworkSummary} from './PrivateNetworkSummary'

import styles from './PrivateNetworkItem.module.css'
import {ListItemTrailingBadge} from '@github-ui/list-view/ListItemTrailingBadge'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

interface IPrivateNetworkItemProps {
  privateNetwork: PrivateNetwork
  showFailoverBadge?: boolean
  onRemove?: (removedPrivateNetwork: PrivateNetwork) => void
  onToggle?: (toggledPrivateNetwork: PrivateNetwork) => void
}

const formBoxStyle = {
  display: 'grid',
  gridTemplateColumns: '1fr',
  borderColor: 'border.default',
  rowGap: 3,
}

export function PrivateNetworkItem(props: IPrivateNetworkItemProps) {
  const [showEditDialog, setShowEditDialog] = useState<boolean>(false)
  const onEditDialogClose = useCallback(() => {
    setShowEditDialog(false)
  }, [])

  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const failoverFeatureEnabled = useFeatureFlag('actions_runner_private_network_failover_enabled')
  const isFailover = props.showFailoverBadge || props.privateNetwork.isFailover
  const isEnabled = props.privateNetwork.enabled

  const trailingBadges = failoverFeatureEnabled
    ? [
        ...(isFailover ? [<ListItemTrailingBadge title="Failover" key="failover" />] : []),
        ...(isEnabled ? [<ListItemTrailingBadge title="Enabled" key="enabled" variant="success" />] : []),
      ]
    : []

  const renderFooter = () => {
    if (props.onRemove) {
      return (
        <Dialog.Footer
          sx={{
            display: 'flex',
            flexDirection: 'row',
            justifyContent: 'space-between',
          }}
        >
          <Button variant="danger" onClick={() => props.onRemove && props.onRemove(props.privateNetwork)}>
            Remove network
          </Button>
          <Button onClick={() => setShowEditDialog(false)}>Close</Button>
        </Dialog.Footer>
      )
    }
    return null
  }
  return (
    <>
      {showEditDialog && (
        <Dialog
          title={props.privateNetwork.resourceName}
          onClose={onEditDialogClose}
          renderFooter={renderFooter}
          width="large"
        >
          <Box sx={formBoxStyle}>
            <FormControl>
              <FormControl.Label>{PrivateNetworkConsts.azureNetworkResourceIdLabel}</FormControl.Label>
              <TextInput
                type="text"
                readOnly
                contrast
                className={styles.FullWidthInput}
                value={props.privateNetwork.id}
              />
            </FormControl>
            <PrivateNetworkSummary privateNetwork={props.privateNetwork} />
          </Box>
        </Dialog>
      )}
      <ListItem
        title={
          <ListItemTitle
            value={props.privateNetwork.resourceName}
            onClick={() => setShowEditDialog(true)}
            containerClassName={styles.ListItemTitle_0}
            anchorClassName={styles.ListItemTitle_1}
            trailingBadges={trailingBadges}
          />
        }
        metadata={
          <ListItemMetadata alignment="right">
            {failoverFeatureEnabled && props.privateNetwork.isFailover && props.onToggle && (
              <Button
                variant={'default'}
                onClick={() => props.onToggle && props.onToggle(props.privateNetwork)}
                aria-label={`${props.privateNetwork.enabled ? 'Disable' : 'Enable'} failover network ${
                  props.privateNetwork.resourceName
                }`}
              >
                {props.privateNetwork.enabled ? 'Disable' : 'Enable'}
              </Button>
            )}

            {props.onRemove && (
              // eslint-disable-next-line primer-react/a11y-remove-disable-tooltip
              <IconButton
                unsafeDisableTooltip
                icon={TrashIcon}
                aria-label="Delete icon"
                size="medium"
                variant="invisible"
                onClick={() => props.onRemove && props.onRemove(props.privateNetwork)}
                sx={{color: 'fg.muted'}}
              />
            )}
          </ListItemMetadata>
        }
      >
        <ListItemLeadingContent>
          <ListItemLeadingVisual icon={PackageIcon} description="Private Network Icon" />
        </ListItemLeadingContent>
        <ListItemMainContent>
          <ListItemDescription>
            Subscription: {props.privateNetwork.subscription} · Region: {props.privateNetwork.location} · Subnet:{' '}
            {props.privateNetwork.subnet}
          </ListItemDescription>
        </ListItemMainContent>
      </ListItem>
    </>
  )
}
