import {Box, Button} from '@primer/styled-react'
import {ListView} from '@github-ui/list-view'
import type {PrivateNetwork} from '../classes/private-network'
import {PrivateNetworkConsts} from '../constants/private-network-consts'
import {PrivateNetworkItem} from './PrivateNetworkItem'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

interface ICommonProps {
  ariaLabelledBy?: string
  ariaDescribedBy?: string
  validationStatus?: 'error' | 'success'
}
export interface IEmptyStateCardProps extends ICommonProps {
  privateNetworks: []
  enabledForCodespaces: boolean
  onShowNewDialog: () => void
}
export interface IPopulatedListProps extends ICommonProps {
  privateNetworks: PrivateNetwork[]
  failoverPrivateNetworks?: PrivateNetwork[]
  hideEmptyStateCard?: boolean
  onRemove?: (removedPrivateNetwork: PrivateNetwork) => void
  onRemoveFailover?: (removedPrivateNetwork: PrivateNetwork) => void
  onToggle?: (toggledPrivateNetwork: PrivateNetwork) => void
  onShowNewFailoverDialog?: () => void
}
export type IPrivateNetworkListProps = IEmptyStateCardProps | IPopulatedListProps

export function PrivateNetworkList(props: IPrivateNetworkListProps) {
  const populatedProps = props as IPopulatedListProps
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const failoverFeatureEnabled = useFeatureFlag('actions_runner_private_network_failover_enabled')
  const failoverNetworks = failoverFeatureEnabled ? (populatedProps.failoverPrivateNetworks ?? []) : []
  const hasPrimaryNetwork = populatedProps.privateNetworks.length > 0
  const hasFailoverNetwork = failoverNetworks.length > 0
  const showEmptyState = failoverFeatureEnabled ? !hasPrimaryNetwork || !hasFailoverNetwork : !hasPrimaryNetwork

  const emptyStateCard = showEmptyState && !populatedProps.hideEmptyStateCard && (
    <Box
      sx={{
        border: '1px solid',
        borderColor: props.validationStatus === 'error' ? 'danger.emphasis' : 'border.default',
        borderRadius: '6px',
        width: '100%',
      }}
    >
      <EmptyStateCard
        {...(props as IEmptyStateCardProps)}
        hasPrimaryNetwork={hasPrimaryNetwork}
        onShowNewFailoverDialog={populatedProps.onShowNewFailoverDialog}
      />
    </Box>
  )

  const listView = (hasPrimaryNetwork || hasFailoverNetwork) && (
    <Box
      sx={{
        border: '1px solid',
        borderColor: props.validationStatus === 'error' ? 'danger.emphasis' : 'border.default',
        borderRadius: '6px',
        width: '100%',
      }}
    >
      <ListView title="Private Network List" variant="default" ariaLabelledBy={props.ariaLabelledBy}>
        {populatedProps.privateNetworks.map(network => {
          return <PrivateNetworkItem key={network.id} privateNetwork={network} onRemove={populatedProps.onRemove} />
        })}
        {failoverNetworks.map(network => {
          return (
            <PrivateNetworkItem
              key={network.id}
              privateNetwork={network}
              onRemove={populatedProps.onRemoveFailover}
              onToggle={populatedProps.onToggle}
              showFailoverBadge
            />
          )
        })}
      </ListView>
    </Box>
  )

  return (
    <>
      {/* Show empty state first if no primary network */}
      {!hasPrimaryNetwork && emptyStateCard}
      {listView}
      {/* Show empty state last if has primary but no failover (only when failover feature is enabled) */}
      {failoverFeatureEnabled && hasPrimaryNetwork && !hasFailoverNetwork && emptyStateCard}
    </>
  )
}

function EmptyStateCard(
  cardProps: IEmptyStateCardProps & {hasPrimaryNetwork?: boolean; onShowNewFailoverDialog?: () => void},
) {
  const handleButtonClick = () => {
    if (cardProps.hasPrimaryNetwork && cardProps.onShowNewFailoverDialog) {
      cardProps.onShowNewFailoverDialog()
    } else {
      cardProps.onShowNewDialog()
    }
  }
  const buttonLabel = cardProps.hasPrimaryNetwork
    ? PrivateNetworkConsts.addFailoverNetwork
    : PrivateNetworkConsts.addAzureVirtualNetwork

  return (
    <Box
      sx={{
        padding: 48,
        display: 'flex',
        alignItems: 'center',
        flexDirection: 'column',
      }}
    >
      {cardProps.privateNetworks.length === 0 && (
        <Box sx={{fontSize: '16px', color: 'fg.default', fontWeight: 'bold'}}>
          {PrivateNetworkConsts.noAzurePrivateNetworksAdded}
        </Box>
      )}

      {!cardProps.enabledForCodespaces && (
        <Button
          onClick={handleButtonClick}
          aria-labelledby={cardProps.ariaLabelledBy}
          aria-describedby={cardProps.ariaDescribedBy}
          sx={{marginTop: 3}}
        >
          {buttonLabel}
        </Button>
      )}
    </Box>
  )
}
